arguments.content:
:root {
  --ink: #f8ead4;
  --ink-dim: rgba(248, 234, 212, 0.64);
  --coral: #ef8b64;
  --line: rgba(248, 234, 212, 0.28);
  --deep: #092c38;
  --serif: Georgia, "Times New Roman", serif;
  --sans: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--deep);
}

body {
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

#stage {
  position: relative;
  width: 100vw;
  height: 100svh;
  min-height: 420px;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(circle at 24% 50%, #f8b78e 0%, transparent 42%),
    linear-gradient(#345a77, #f3b193 55%, #0c4652);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.ui {
  position: absolute;
  inset: 0;
  z-index: 4;
  padding: clamp(20px, 3.6vw, 54px);
  pointer-events: none;
  opacity: 0;
  animation: ui-in 1.4s 0.35s cubic-bezier(0.2, 0.7, 0.2, 1) forwards;
}

.masthead {
  position: absolute;
  top: clamp(20px, 3.6vw, 54px);
  left: clamp(20px, 3.6vw, 54px);
  display: flex;
  align-items: center;
  gap: 13px;
}

.monogram {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(248, 234, 212, 0.65);
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 16px;
  letter-spacing: -0.08em;
  color: var(--ink);
  background: rgba(9, 44, 56, 0.18);
  backdrop-filter: blur(3px);
}

.monogram span {
  color: var(--coral);
}

.brand {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1;
}

.brand-name {
  font-family: var(--serif);
  font-size: 17px;
  letter-spacing: 0.16em;
}

.brand-sub {
  color: var(--ink-dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.36em;
}

.edition {
  position: absolute;
  top: clamp(20px, 3.6vw, 54px);
  right: clamp(20px, 3.6vw, 54px);
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(248, 234, 212, 0.75);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.24em;
}

.edition-line {
  width: clamp(26px, 4vw, 62px);
  height: 1px;
  background: var(--line);
}

.title-lockup {
  position: absolute;
  left: clamp(20px, 3.6vw, 54px);
  bottom: clamp(76px, 11.5vh, 142px);
  width: min(360px, 45vw);
  text-shadow: 0 2px 26px rgba(5, 33, 41, 0.28);
}

.eyebrow {
  margin: 0 0 17px;
  color: rgba(248, 234, 212, 0.74);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.3em;
}

.title-lockup h1 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(49px, 6.9vw, 106px);
  font-weight: 400;
  line-height: 0.82;
  letter-spacing: -0.055em;
}

.title-lockup h1 em {
  color: #ffd8b6;
  font-weight: 400;
  padding-left: 0.3em;
}

.title-note {
  margin: 20px 0 0;
  color: rgba(248, 234, 212, 0.72);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 14px);
  letter-spacing: 0.02em;
}

.readout {
  position: absolute;
  left: clamp(20px, 3.6vw, 54px);
  bottom: clamp(28px, 4.2vh, 54px);
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(248, 234, 212, 0.7);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.22em;
}

.readout-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 10px rgba(239, 139, 100, 0.85);
  animation: pulse 2.4s ease-in-out infinite;
}

.readout-divider {
  width: 18px;
  height: 1px;
  background: var(--line);
}

.hint {
  position: absolute;
  right: clamp(20px, 3.6vw, 54px);
  bottom: clamp(28px, 4.2vh, 54px);
  color: rgba(248, 234, 212, 0.55);
  font-size: 7px;
  font-weight: 500;
  letter-spacing: 0.19em;
}

.hint-key {
  color: rgba(248, 234, 212, 0.92);
  font-weight: 700;
}

.hint-sep {
  padding: 0 7px;
  color: rgba(248, 234, 212, 0.3);
}

.frame-line {
  position: absolute;
  left: clamp(20px, 3.6vw, 54px);
  right: clamp(20px, 3.6vw, 54px);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--line) 18%, var(--line) 82%, transparent);
  opacity: 0.42;
}

.frame-line--top {
  top: clamp(76px, 10vw, 130px);
  display: none;
}

.frame-line--bottom {
  bottom: clamp(56px, 7.2vh, 84px);
  display: none;
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 27, 35, 0.22) 0%, transparent 18%, transparent 66%, rgba(4, 27, 35, 0.34) 100%),
    radial-gradient(ellipse at 50% 48%, transparent 48%, rgba(4, 25, 32, 0.3) 120%);
}

.grain {
  position: absolute;
  inset: -20%;
  z-index: 5;
  pointer-events: none;
  opacity: 0.065;
  background-image:
    repeating-radial-gradient(circle at 17% 32%, rgba(255, 255, 255, 0.9) 0 0.6px, transparent 0.8px 3.2px),
    repeating-radial-gradient(circle at 73% 61%, rgba(0, 0, 0, 0.8) 0 0.5px, transparent 0.8px 4px);
  background-size: 7px 7px, 9px 9px;
  animation: grain-shift 0.6s steps(2) infinite;
  mix-blend-mode: soft-light;
}

.curtain {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  background: #092c38;
  animation: curtain-out 1.6s 0.05s cubic-bezier(0.76, 0, 0.24, 1) forwards;
}

@keyframes ui-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes curtain-out {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    visibility: hidden;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes grain-shift {
  0% {
    transform: translate(0, 0);
  }
  25% {
    transform: translate(-1.5%, 1%);
  }
  50% {
    transform: translate(1%, -1.5%);
  }
  75% {
    transform: translate(-1%, -0.5%);
  }
  100% {
    transform: translate(0.5%, 1%);
  }
}

@media (max-width: 760px) {
  .title-lockup {
    bottom: 94px;
    width: 62vw;
  }

  .title-lockup h1 {
    font-size: clamp(44px, 13vw, 82px);
  }

  .title-note {
    max-width: 180px;
    line-height: 1.35;
  }

  .edition {
    display: none;
  }

  .hint {
    right: auto;
    left: clamp(20px, 3.6vw, 54px);
    bottom: 16px;
  }

  .readout {
    display: none;
  }

  .masthead {
    gap: 9px;
  }

  .brand-name {
    font-size: 14px;
  }
}

@media (max-height: 560px) {
  .title-lockup {
    bottom: 54px;
  }

  .title-lockup h1 {
    font-size: clamp(38px, 8vh, 70px);
  }

  .eyebrow,
  .title-note {
    display: none;
  }

  .readout {
    bottom: 18px;
  }

  .hint {
    bottom: 18px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ui,
  .curtain,
  .grain,
  .readout-dot {
    animation: none;
  }

  .ui {
    opacity: 1;
  }

  .curtain {
    display: none;
  }
}

import * as THREE from "three";
import "./styles.css";

/* -------------------------------------------------------------------------- */
/*  The Surfing Pelican                                                       */
/*  A tiny, entirely procedural golden-hour scene. No external assets.        */
/* -------------------------------------------------------------------------- */

const canvas = document.querySelector("#scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: "high-performance",
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.outputColorSpace = THREE.SRGBColorSpace;

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xf2ac86, 38, 165);

const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 420);
const CAMERA_BASE = new THREE.Vector3(3.25, 3.15, 8.8);
const LOOK_BASE = new THREE.Vector3(0.1, 1.72, 0);
camera.position.copy(CAMERA_BASE);

const clock = new THREE.Clock();
let elapsed = 0;

const pointer = {
  x: 0,
  y: 0,
  smoothX: 0,
  smoothY: 0,
  active: false,
};

const tempVec = new THREE.Vector3();
const tempColor = new THREE.Color();

/* -------------------------------------------------------------------------- */
/*  Small helpers                                                             */
/* -------------------------------------------------------------------------- */

const PI = Math.PI;
const TAU = Math.PI * 2;

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function smoothstep(min, max, v) {
  const x = clamp((v - min) / (max - min), 0, 1);
  return x * x * (3 - 2 * x);
}

function randomBetween(min, max) {
  return min + Math.random() * (max - min);
}

function makeCanvasTexture(width, height, draw) {
  const c = document.createElement("canvas");
  c.width = width;
  c.height = height;
  const ctx = c.getContext("2d");
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(c);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}

function makeGlowTexture(size = 256) {
  return makeCanvasTexture(size, size, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,255,255,1)");
    g.addColorStop(0.18, "rgba(255,250,235,0.95)");
    g.addColorStop(0.46, "rgba(255,228,188,0.38)");
    g.addColorStop(0.72, "rgba(255,204,160,0.08)");
    g.addColorStop(1, "rgba(255,200,150,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

function makeCloudTexture(seed = 1) {
  return makeCanvasTexture(1024, 512, (ctx, w, h) => {
    let rand = seed * 9721;
    const rnd = () => {
      rand = (rand * 16807) % 2147483647;
      return (rand - 1) / 2147483646;
    };

    ctx.clearRect(0, 0, w, h);

    const puffs = 20;
    for (let i = 0; i < puffs; i++) {
      const x = w * (0.16 + rnd() * 0.68);
      const y = h * (0.36 + rnd() * 0.28 - (x / w - 0.5) * 0.1);
      const rx = w * (0.08 + rnd() * 0.19);
      const ry = h * (0.05 + rnd() * 0.10);
      const g = ctx.createRadialGradient(x, y, 0, x, y, 1);
      const shade = 0.75 + rnd() * 0.25;
      g.addColorStop(0, `rgba(255, ${Math.round(240 * shade)}, ${Math.round(228 * shade)}, ${0.2 + rnd() * 0.16})`);
      g.addColorStop(0.46, `rgba(255, ${Math.round(228 * shade)}, ${Math.round(214 * shade)}, ${0.11 + rnd() * 0.1})`);
      g.addColorStop(1, "rgba(255,225,210,0)");
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(rx, ry);
      ctx.translate(-x, -y);
      ctx.fillStyle = g;
      ctx.fillRect(x - rx, y - ry, rx * 2, ry * 2);
      ctx.restore();
    }

    // A few soft horizontal wisps give the cloud its painted silhouette.
    for (let i = 0; i < 5; i++) {
      const y = h * (0.48 + i * 0.028);
      const g = ctx.createLinearGradient(w * 0.12, 0, w * 0.9, 0);
      g.addColorStop(0, "rgba(255,225,210,0)");
      g.addColorStop(0.35, "rgba(255,232,218,0.10)");
      g.addColorStop(0.62, "rgba(255,219,205,0.055)");
      g.addColorStop(1, "rgba(255,225,210,0)");
      ctx.fillStyle = g;
      ctx.fillRect(w * 0.08, y, w * 0.86, h * 0.018);
    }
  });
}

/* -------------------------------------------------------------------------- */
/*  Palette & shared materials                                                */
/* -------------------------------------------------------------------------- */

const PALETTE = {
  skyTop: 0x24415f,
  skyMid: 0x7f8da2,
  horizon: 0xf7b28c,
  sun: 0xffdca8,
  deepWater: 0x073e4d,
  shallowWater: 0x18808a,
  crestWater: 0x53c4b6,
  foam: 0xf8ead6,
  cream: 0xf2e4cd,
  creamShadow: 0xd9c6ad,
  featherDark: 0x263b45,
  bill: 0xdf8033,
  billLight: 0xf4ad51,
  pouch: 0xf1b75b,
  shorts: 0x123d46,
  shortsLight: 0x2d6a6b,
  coral: 0xed7e59,
};

const MAT = {
  cream: new THREE.MeshStandardMaterial({
    color: PALETTE.cream,
    roughness: 0.82,
    metalness: 0,
  }),
  creamSoft: new THREE.MeshStandardMaterial({
    color: 0xf8eedb,
    roughness: 0.9,
    metalness: 0,
  }),
  creamShadow: new THREE.MeshStandardMaterial({
    color: PALETTE.creamShadow,
    roughness: 0.92,
  }),
  feather: new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.76,
    metalness: 0,
    side: THREE.DoubleSide,
  }),
  bill: new THREE.MeshPhysicalMaterial({
    color: PALETTE.bill,
    roughness: 0.44,
    metalness: 0,
    clearcoat: 0.32,
    clearcoatRoughness: 0.52,
  }),
  billTip: new THREE.MeshStandardMaterial({
    color: 0xb94f2b,
    roughness: 0.43,
  }),
  pouch: new THREE.MeshPhysicalMaterial({
    color: PALETTE.pouch,
    roughness: 0.62,
    metalness: 0,
    sheen: 0.65,
    sheenColor: new THREE.Color(0xffd68a),
    sheenRoughness: 0.7,
  }),
  leg: new THREE.MeshStandardMaterial({
    color: 0xe9953e,
    roughness: 0.62,
  }),
  shorts: new THREE.MeshStandardMaterial({
    color: PALETTE.shorts,
    roughness: 0.78,
  }),
  shortsTrim: new THREE.MeshStandardMaterial({
    color: 0xebd6b5,
    roughness: 0.75,
  }),
  sunglasses: new THREE.MeshPhysicalMaterial({
    color: 0x0d3034,
    roughness: 0.09,
    metalness: 0.4,
    clearcoat: 1,
    clearcoatRoughness: 0.04,
  }),
  gold: new THREE.MeshStandardMaterial({
    color: 0xd9a554,
    roughness: 0.27,
    metalness: 0.72,
  }),
  board: new THREE.MeshPhysicalMaterial({
    color: PALETTE.coral,
    roughness: 0.38,
    metalness: 0.02,
    clearcoat: 0.72,
    clearcoatRoughness: 0.2,
  }),
  boardStripe: new THREE.MeshPhysicalMaterial({
    color: 0xf5e8cf,
    roughness: 0.44,
    clearcoat: 0.48,
    clearcoatRoughness: 0.3,
  }),
  boardDark: new THREE.MeshStandardMaterial({
    color: 0x113e48,
    roughness: 0.42,
    metalness: 0.12,
  }),
  coral: new THREE.MeshStandardMaterial({
    color: PALETTE.coral,
    roughness: 0.7,
  }),
  flower: new THREE.MeshStandardMaterial({
    color: 0xf19a83,
    roughness: 0.7,
    side: THREE.DoubleSide,
  }),
  flowerLight: new THREE.MeshStandardMaterial({
    color: 0xffd4bd,
    roughness: 0.7,
    side: THREE.DoubleSide,
  }),
  flowerCenter: new THREE.MeshStandardMaterial({
    color: 0xf4c85f,
    roughness: 0.7,
  }),
};

/* -------------------------------------------------------------------------- */
/*  Sky                                                                       */
/* -------------------------------------------------------------------------- */

const SUN_DIRECTION = new THREE.Vector3(-0.62, 0.095, -0.78).normalize();

const skyMaterial = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  depthWrite: false,
  fog: false,
  uniforms: {
    uSunDirection: { value: SUN_DIRECTION.clone() },
    uTop: { value: new THREE.Color(PALETTE.skyTop) },
    uMid: { value: new THREE.Color(PALETTE.skyMid) },
    uHorizon: { value: new THREE.Color(PALETTE.horizon) },
    uSun: { value: new THREE.Color(PALETTE.sun) },
    uTime: { value: 0 },
  },
  vertexShader: /* glsl */ `
    varying vec3 vDirection;
    void main() {
      vDirection = normalize(position);
      vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
      gl_Position = projectionMatrix * mvPosition;
    }
  `,
  fragmentShader: /* glsl */ `
    uniform vec3 uSunDirection;
    uniform vec3 uTop;
    uniform vec3 uMid;
    uniform vec3 uHorizon;
    uniform vec3 uSun;
    uniform float uTime;
    varying vec3 vDirection;

    float hash(vec2 p) {
      p = fract(p * vec2(123.34, 456.21));
      p += dot(p, p + 45.32);
      return fract(p.x * p.y);
    }

    float noise(vec2 p) {
      vec2 i = floor(p);
      vec2 f = fract(p);
      f = f * f * (3.0 - 2.0 * f);
      float a = hash(i);
      float b = hash(i + vec2(1.0, 0.0));
      float c = hash(i + vec2(0.0, 1.0));
      float d = hash(i + vec2(1.0, 1.0));
      return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }

    float fbm(vec2 p) {
      float v = 0.0;
      float a = 0.5;
      for (int i = 0; i < 4; i++) {
        v += a * noise(p);
        p = p * 2.03 + 11.1;
        a *= 0.5;
      }
      return v;
    }

    void main() {
      vec3 dir = normalize(vDirection);
      float y = dir.y;
      float sunDot = max(dot(dir, normalize(uSunDirection)), 0.0);

      float upT = smoothstep(-0.02, 0.78, y);
      vec3 color = mix(uHorizon, uMid, smoothstep(0.0, 0.26, upT));
      color = mix(color, uTop, smoothstep(0.28, 1.0, upT));

      // A soft, dusty violet belt opposite the sunset.
      float antiSun = smoothstep(0.2, 0.9, -dot(normalize(vec3(uSunDirection.x, 0.0, uSunDirection.z)), normalize(vec3(dir.x, 0.001, dir.z))));
      color = mix(color, vec3(0.42, 0.42, 0.52), antiSun * 0.16 * smoothstep(0.05, 0.45, y));

      // Warm atmospheric bloom around the low sun.
      float glow = pow(sunDot, 7.0) * 0.26 + pow(sunDot, 32.0) * 0.42 + pow(sunDot, 180.0) * 0.55;
      color += uSun * glow;
      color += vec3(0.22, 0.11, 0.05) * pow(sunDot, 2.3) * 0.45;

      // The sun itself, with a little organic irregularity.
      float disk = smoothstep(0.99945, 0.99982, sunDot);
      float rim = smoothstep(0.9988, 0.99945, sunDot) * 0.2;
      color = mix(color, uSun * 1.3, disk);
      color += vec3(1.0, 0.81, 0.57) * rim;

      // High, painterly cirrus streaks.
      vec2 sphereUv = vec2(atan(dir.z, dir.x) * 1.65, dir.y * 4.0);
      float streakNoise = fbm(vec2(sphereUv.x * 0.75 + uTime * 0.002, sphereUv.y * 2.3));
      float streaks = smoothstep(0.59, 0.76, streakNoise) *
        smoothstep(0.035, 0.21, y) * (1.0 - smoothstep(0.52, 0.82, y));
      vec3 cloudTint = mix(vec3(0.87, 0.61, 0.58), vec3(0.98, 0.82, 0.68), pow(sunDot, 1.8));
      color = mix(color, cloudTint, streaks * 0.18);

      // Fine dithering keeps the enormous gradient from banding.
      float dither = hash(gl_FragCoord.xy) / 255.0 - 0.5 / 255.0;
      color += dither;

      gl_FragColor = vec4(color, 1.0);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }
  `,
});

const sky = new THREE.Mesh(new THREE.SphereGeometry(240, 48, 32), skyMaterial);
sky.renderOrder = -100;
scene.add(sky);

// Sun halo sprite — adds a soft, photographic core above the horizon.
const glowTexture = makeGlowTexture(256);
const sunGlow = new THREE.Sprite(
  new THREE.SpriteMaterial({
    map: glowTexture,
    color: 0xffd0a1,
    transparent: true,
    opacity: 0.8,
    depthWrite: false,
    depthTest: false,
    blending: THREE.AdditiveBlending,
    fog: false,
  })
);
sunGlow.position.copy(SUN_DIRECTION).multiplyScalar(185);
sunGlow.position.y = 29;
sunGlow.scale.set(58, 58, 1);
sunGlow.renderOrder = -50;
scene.add(sunGlow);

// Wispy, layered cloud sprites — painterly rather than photographic.
const cloudSprites = [];
for (let i = 0; i < 5; i++) {
  const texture = makeCloudTexture(i + 2);
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: texture,
      color: i % 2 ? 0xdfb7a8 : 0xf3c8b2,
      transparent: true,
      opacity: 0.34 + i * 0.035,
      depthWrite: false,
      fog: false,
      blending: THREE.NormalBlending,
    })
  );
  const positions = [
    [-42, 26, -105, 62, 22],
    [36, 34, -120, 72, 25],
    [-8, 17, -130, 90, 20],
    [76, 23, -95, 54, 16],
    [-88, 40, -80, 45, 16],
  ];
  const p = positions[i];
