const waterUniforms = {
  uTime: { value: 0 },
  uSunDirection: { value: SUN_DIRECTION.clone() },
  uOrigin: { value: new THREE.Vector2(0, -38) },
  uBoardPosition: { value: new THREE.Vector2(0.1, 0.8) },
  uDeep: { value: new THREE.Color(PALETTE.deepWater) },
  uShallow: { value: new THREE.Color(PALETTE.shallowWater) },
  uCrest: { value: new THREE.Color(PALETTE.crestWater) },
  uFoam: { value: new THREE.Color(PALETTE.foam) },
  uHorizon: { value: new THREE.Color(PALETTE.horizon) },
  uSky: { value: new THREE.Color(PALETTE.skyMid) },
  uSun: { value: new THREE.Color(0xffd29c) },
};

const waterMaterial = new THREE.ShaderMaterial({
  uniforms: waterUniforms,
  vertexShader: /* glsl */ `
    uniform float uTime;
    uniform vec2 uOrigin;
    varying vec3 vWorldPosition;
    varying vec3 vNormal;
    varying float vHeight;
    varying float vHero;

    float heroWave(vec2 p) {
      float wobble = 2.0 * sin(p.x * 0.095 + 0.35) + 0.8 * sin(p.x * 0.31 + uTime * 0.14);
      float across = exp(-pow((p.y + 3.9 + wobble) / 3.4, 2.0));
      float along = 0.48 + 0.78 * smoothstep(-20.0, 6.0, p.x);
      float shape = 1.0 + 0.12 * sin(p.x * 0.42 + 1.1);
      return across * along * shape * 2.55;
    }

    float backSwell(vec2 p) {
      float across = exp(-pow((p.y + 17.0 + 2.5 * sin(p.x * 0.07 + 0.8)) / 6.5, 2.0));
      return across * (0.7 + 0.25 * sin(p.x * 0.12 + 2.0)) * 1.1;
    }

    float waveHeight(vec2 p) {
      float h = 0.0;
      h += sin(p.x * 0.23 + p.y * 0.14 + uTime * 0.63) * 0.14;
      h += sin(p.x * 0.42 - p.y * 0.30 - uTime * 0.92) * 0.075;
      h += sin(p.x * 0.83 + p.y * 0.22 + uTime * 1.35) * 0.030;
      h += sin(p.x * 0.30 - p.y * 0.63 + uTime * 0.47) * 0.045;
      h += heroWave(p);
      h += backSwell(p);
      return h;
    }

    void main() {
      vec2 p = position.xz + uOrigin;
      float h = waveHeight(p);
      float eps = 0.28;
      float hx = waveHeight(p + vec2(eps, 0.0));
      float hz = waveHeight(p + vec2(0.0, eps));
      vec3 n = normalize(vec3(-(hx - h) / eps, 1.0, -(hz - h) / eps));

      vec3 displaced = vec3(position.x, h, position.z);
      vec4 worldPos = modelMatrix * vec4(displaced, 1.0);
      vWorldPosition = worldPos.xyz;
      vNormal = normalize(mat3(modelMatrix) * n);
      vHeight = h;
      vHero = heroWave(p);
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: /* glsl */ `
    uniform float uTime;
    uniform vec2 uBoardPosition;
    uniform vec3 uSunDirection;
    uniform vec3 uDeep;
    uniform vec3 uShallow;
    uniform vec3 uCrest;
    uniform vec3 uFoam;
    uniform vec3 uHorizon;
    uniform vec3 uSky;
    uniform vec3 uSun;
    varying vec3 vWorldPosition;
    varying vec3 vNormal;
    varying float vHeight;
    varying float vHero;

    float hash(vec2 p) {
      p = fract(p * vec2(123.34, 456.21));
      p += dot(p, p + 45.32);
      return fract(p.x * p.y);
    }

    float noise(vec2 p) {
      vec2 i = floor(p);
      vec2 f = fract(p);
      f = f * f * (3.0 - 2.0 * f);
      float a = hash(i);
      float b = hash(i + vec2(1.0, 0.0));
      float c = hash(i + vec2(0.0, 1.0));
      float d = hash(i + vec2(1.0, 1.0));
      return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }

    float fbm(vec2 p) {
      float v = 0.0;
      float a = 0.5;
      for (int i = 0; i < 4; i++) {
        v += a * noise(p);
        p = p * 2.02 + vec2(9.7, 3.1);
        a *= 0.5;
      }
      return v;
    }

    void main() {
      vec3 N = normalize(vNormal);
      vec3 V = normalize(cameraPosition - vWorldPosition);
      vec3 L = normalize(uSunDirection);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 4.0);
      float heightTone = smoothstep(-0.45, 2.5, vHeight);
      float crestTone = smoothstep(0.8, 2.55, vHeight + vHero * 0.2);

      vec3 water = mix(uDeep, uShallow, 0.38 + heightTone * 0.52);
      water = mix(water, uCrest, crestTone * 0.42 + fresnel * 0.10);

      vec3 reflected = reflect(-V, N);
      float skyT = smoothstep(-0.03, 0.5, reflected.y);
      vec3 skyReflection = mix(uHorizon, uSky, skyT);
      water = mix(water, skyReflection, 0.10 + fresnel * 0.50);

      float diffuse = max(dot(N, L), 0.0);
      water += uSun * diffuse * 0.10;

      float sunSpec = pow(max(dot(reflect(-L, N), V), 0.0), 170.0);
      float sunBroad = pow(max(dot(reflect(-L, N), V), 0.0), 16.0);
      water += uSun * (sunSpec * 2.0 + sunBroad * 0.17);

      // Moving glitter, broken into tiny warm sparks.
      vec2 sparkleP = vWorldPosition.xz * 2.9 + vec2(uTime * 0.35, -uTime * 0.17);
      float sparkle = smoothstep(0.84, 0.99, hash(floor(sparkleP)) * (0.4 + fbm(sparkleP)));
      float sparkleMask = smoothstep(0.35, 0.9, sunBroad * 8.0 + diffuse * 0.2);
      water += uSun * sparkle * sparkleMask * 0.7;

      // The long, warm path of light under the sun.
      vec2 toSun = normalize(-uSunDirection.xz);
      vec2 relSun = vWorldPosition.xz * vec2(0.12, 0.28);
      float lightPath = exp(-abs(relSun.x - toSun.x * 1.0) * 2.8);
      water += uSun * lightPath * (0.022 + sunBroad * 0.35);

      // Foam collects on the big swell's lip and streams down its face.
      vec2 foamUv = vWorldPosition.xz;
      float foamNoise = fbm(foamUv * 0.47 + vec2(uTime * 0.055, -uTime * 0.075));
      float foamNoise2 = fbm(foamUv * 1.27 + vec2(-uTime * 0.15, uTime * 0.12));
      float heroCrest = smoothstep(1.15, 2.28, vHeight) * smoothstep(0.35, 1.1, vHero);
      float lipFoam = smoothstep(0.40, 0.74, foamNoise + heroCrest * 0.23);
      float streakFoam = smoothstep(0.63, 0.87, foamNoise2) * smoothstep(0.38, 0.95, vHero);
      float foam = heroCrest * lipFoam * 0.95 + streakFoam * 0.25;
      foam += smoothstep(0.20, 0.32, vHeight) * smoothstep(0.73, 0.92, foamNoise2) * 0.20;

      // A small churn of foam around the travelling board.
      vec2 relBoard = vWorldPosition.xz - uBoardPosition;
      float boardNear = exp(-length(relBoard * vec2(1.0, 2.5)) * 2.0);
      float wake = exp(-length((relBoard - vec2(-1.7, 0.0)) * vec2(0.44, 2.0)) * 1.35);
      float boardChurn = (boardNear * 0.76 + wake * 0.38) * (0.35 + fbm(vWorldPosition.xz * 2.2 + uTime * 0.2) * 0.8);
      foam += boardChurn;

      foam = clamp(foam, 0.0, 1.0);
      vec3 foamColor = mix(uFoam * 0.78, uFoam, smoothstep(0.1, 0.8, foamNoise + diffuse * 0.3));
      water = mix(water, foamColor, foam);

      // A warm, misty horizon dissolves the water into the sky.
      float dist = length(vWorldPosition.xz - cameraPosition.xz);
      float haze = 1.0 - exp(-pow(max(dist - 17.0, 0.0) * 0.0085, 2.0));
      water = mix(water, uHorizon, clamp(haze, 0.0, 0.98));

      float dither = hash(gl_FragCoord.xy) / 255.0 - 0.5 / 255.0;
      water += dither;

      gl_FragColor = vec4(water, 1.0);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }
  `,
});

