import puppeteer from "puppeteer-core";
const browser = await puppeteer.launch({executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",headless:true,args:["--no-sandbox","--use-gl=angle","--enable-webgl","--ignore-gpu-blocklist","--hide-scrollbars"]});
const errors = [];
async function capture(width, height, file, wait=4500) {
  const page = await browser.newPage();
  await page.setViewport({width, height, deviceScaleFactor:1});
  page.on("console", msg => { if (msg.type()==="error" && !msg.text().includes("favicon")) errors.push(msg.text()); });
  page.on("pageerror", err => errors.push(err.message));
  await page.goto("http://127.0.0.1:9137/preview.html", {waitUntil:"networkidle0"});
  await new Promise(r=>setTimeout(r,wait));
  await page.screenshot({path:file,type:"jpeg",quality:90});
  const details = await page.evaluate(()=>({
    title: document.title,
    canvas: [document.querySelector('#scene')?.width, document.querySelector('#scene')?.height],
    gl: !!document.createElement('canvas').getContext('webgl2'),
    storage: (()=>{try{localStorage.getItem('x');return 'available';}catch(e){return 'blocked';}})()
  }));
  await page.close();
  return details;
}
console.log("desktop", await capture(1440,900,"final_desktop.jpg"));
console.log("mobile", await capture(390,844,"final_mobile.jpg",5000));
console.log("errors", errors);
await browser.close();
EOF
